'use strict';
let conversationStage='welcome';
function message(role,text){const item=document.createElement('article');item.className='message '+role;const label=document.createElement('span');label.className='message-role';label.textContent=role==='user'?'你':'来处 · 演示助手';const body=document.createElement('p');body.textContent=text;item.append(label,body);$('conversation').append(item);$('conversation').scrollTop=$('conversation').scrollHeight;return item;}
function suggestions(options){$('suggestions').replaceChildren();for(const [label,action] of options){const button=document.createElement('button');button.type='button';button.textContent=label;button.addEventListener('click',()=>act(action,label));$('suggestions').append(button);}}
function clue(title,copy,stopId){const card=document.createElement('section');card.className='clue-card';const tag=document.createElement('span');tag.className='step';tag.textContent='演示发现 · 待核查';const heading=document.createElement('h2');heading.textContent=title;const p=document.createElement('p');p.textContent=copy;const button=document.createElement('button');button.type='button';button.className='text-button';button.textContent='在地图上查看';button.addEventListener('click',()=>{selectStop(stopId);if(window.innerWidth<760)document.querySelector('.map-shell').scrollIntoView({behavior:reduced?'auto':'smooth'});});const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='依据与缺口';const source=document.createElement('p');source.textContent=stops.find(s=>s.id===stopId).source;details.append(summary,source);card.append(tag,heading,p,button,details);$('conversation').append(card);$('conversation').scrollTop=$('conversation').scrollHeight;}
function followup(){conversationStage='generation';message('assistant','示例里有两组不同字辈。你记得哪一组？这能帮助区分候选支系；不知道也可以继续探索。');suggestions([['英、士、班、家、国','dayuan'],['英、士、中、州、启','yangxin'],['暂时不知道','unknown']]);}
function startDemo(kind){query={demo:true};branch=null;message('assistant',kind==='origin'?'我们先沿“祖上从江西来”这条说法探索。示例材料提到江西乐平，但还缺原谱，暂时只能作为迁出线索。':kind==='culture'?'同姓同乡不一定属于同一支。这个示例里，通山与阳新的两组字辈不同，可以用来演示如何进一步缩小范围。':'字辈是家族命名中的代际线索，不能直接推断某个人的父亲或祖父是谁。先用通山阮氏材料，看看它怎样帮助区分支系。');clue(kind==='origin'?'江西乐平 · 迁出线索':'通山阮氏 · 两组字辈线索',kind==='origin'?'材料提及乐平杏花村迁出说法；原村址与年份待核对。':'英士班家国 / 英士中州启，来自讨论材料，尚未核对谱页。',kind==='origin'?'leping':'tongshan');selectStop(kind==='origin'?'leping':'tongshan');followup();}
function act(action,label){message('user',label);if(['generation-demo','origin-demo','culture-demo'].includes(action)){startDemo(action.split('-')[0]);return;}
if(['dayuan','yangxin','unknown'].includes(action)){branch=action;conversationStage='candidate';const place=action==='yangxin'?'阳新':'通山';message('assistant',action==='unknown'?'我们保留两种可能，不确定所属支系。仍然可以查看材料里的迁徙说法和姓氏文化。':`所选字辈与${place}候选线索相符。这是演示匹配，还缺原谱和亲属记录，不能确认你属于该支。`);clue(action==='unknown'?'两条候选线索，暂不确定':place+' · 候选支系',action==='dayuan'?'英、士、班、家、国：通山大源候选。':action==='yangxin'?'英、士、中、州、启：阳新候选。':'字辈未知，保留通山与阳新两种可能。',action==='yangxin'?'yangxin':'tongshan');selectStop(action==='yangxin'?'yangxin':'tongshan');suggestions([['看看江西迁徙线索','route'],['竹林堂和阮籍有什么关系？','culture'],['我还需要问家里什么？','family'],['重新选择字辈','change']]);return;}
if(action==='route'){message('assistant','地图上已展开乐平、阳新、通山三处候选地点。材料称阮四一于1275年前后从乐平迁往兴国州，但古今地域、迁入村址以及通山分支年代仍待核查。虚线表示材料中的候选联系，不代表实际道路。');revealRoute();clue('三处地点 · 候选迁徙线索','点击地图地点或下方线索栏，可飞到当地查看依据。陈留仅为文化背景，不接入这条路线。','leping');}
else if(action==='culture'){message('assistant','演示材料将竹林堂与阮籍、阮咸联系起来。这可以作为姓氏文化线索，但不能证明他们是你的直系祖先；堂号来源也需要文献核对。');clue('陈留 · 姓氏文化背景','文化联系与个人血缘关系分开展示。','chenliu');selectStop('chenliu');}
else if(action==='family'){message('assistant','可以问长辈一个具体问题：“爷爷或曾祖父原来住哪个村？”如果记得姓名、字辈或旧谱里的地名，也能作为下一条线索。你可以把答案继续写在下方；这版不会保存或公开这些内容。');}
else if(action==='change'){followup();return;}
suggestions([['看看江西迁徙线索','route'],['竹林堂和阮籍有什么关系？','culture'],['我还需要问家里什么？','family'],['重新选择字辈','change']]);}
function submitQuestion(text){if(typeof text!=='string'||!text.trim()||text.length>600)throw new Error('请输入600字以内的问题');text=text.trim();message('user',text);
if(query?.demo&&/英.?士.?班|班.?家.?国/.test(text)){// Process as an answer without repeating the user's text.
 $('conversation').lastElementChild.remove();act('dayuan',text);
}else if(query?.demo&&/英.?士.?中|中.?州.?启/.test(text)){$('conversation').lastElementChild.remove();act('yangxin',text);}
else if(query?.demo&&/不知道|不记得|不清楚/.test(text)){$('conversation').lastElementChild.remove();act('unknown',text);}
else if(/阮/.test(text)&&/通山|阳新|黄沙|大源/.test(text)){startDemo(/江西|迁|哪里来/.test(text)?'origin':'generation');}
else if(query?.demo&&/江西|迁徙|迁来|乐平/.test(text)){$('conversation').lastElementChild.remove();act('route',text);}
else if(query?.demo&&/阮籍|竹林|堂号/.test(text)){$('conversation').lastElementChild.remove();act('culture',text);}
else{message('assistant',query?.demo?'这条信息可以成为后续查询的线索，但当前是固定对话演示，尚不能检索或核对新内容。你可以继续探索下方示例问题。':'这版还没有接入真实 AI 和网络检索，因此无法为这个问题生成有依据的家族结果。可以先选择下方阮氏示例，体验“提问—追问—地图变化”。');if(!query?.demo)welcomeSuggestions();}
return {stage:conversationStage,demoOnly:true};}
function welcomeSuggestions(){suggestions([['阮氏示例：字辈能说明什么？','generation-demo'],['阮氏示例：祖上从江西来？','origin-demo'],['阮氏示例：同姓就是一家吗？','culture-demo']]);}
function resetConversation(){query=null;branch=null;conversationStage='welcome';window.routeRevealed=false;$('conversation').replaceChildren();$('question').value='';if(ready)map.setLayoutProperty('route-line','visibility','none');$('map-heading').textContent='探索背景 · 阮氏演示';$('route-caption').textContent='先探索背景地点，对话后展开候选路线';message('assistant','你最想知道家里的哪件事？可以直接提问，也可以从一个阮氏示例开始。右侧是可先探索的背景线索，不代表你的祖先。');welcomeSuggestions();overview();}
$('chat-form').addEventListener('submit',e=>{e.preventDefault();submitQuestion($('question').value);$('question').value='';});$('question').addEventListener('keydown',e=>{if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){$('chat-form').requestSubmit();}});$('reset-chat').addEventListener('click',resetConversation);resetConversation();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const tool={name:'ask_family_demo',description:'向固定溯源对话演示提交问题，更新对话与地图；不进行真实检索。',inputSchema:{type:'object',properties:{question:{type:'string',minLength:1,maxLength:600}},required:['question'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>submitQuestion(input?.question)};try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
